private fun symbol(
    name: String,
    size: Int,
    viewport: Pair<Float, Float>,
    translateY: Float,
    autoMirror: Boolean,
    vararg pathData: String,
): ImageVector {
    val builder = ImageVector.Builder(
        name = name,
        defaultWidth = size.dp,
        defaultHeight = size.dp,
        viewportWidth = viewport.first,
        viewportHeight = viewport.second,
        autoMirror = autoMirror,
    )
    // Symbols SVGs use viewBox 0 -960 960 960: shift the paths down into the viewport.
    builder.addGroup(translationY = translateY)
    pathData.forEach { d -> builder.addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black)) }
    builder.clearGroup()
    return builder.build()
}
